from robot_model import P, LT, UT, CZ, BZ, SY_FRONT, SZ, BX, BY, BH, BT
PAGES=[]
def page(title,stage,new,need,action,check,arrows=(),lift=0,view=None):PAGES.append(dict(kind='build',title=title,stage=stage,new=new,need=need,action=action,check=check,arrows=arrows,lift=lift,view=view))
PAGES.append(dict(kind='cover',title='Мандрівник'))
PAGES.append(dict(kind='teacher',title='Спочатку перевіряє вчитель'))
