PAGES.append(dict(kind='inventory',title='Що додаємо до набору',which=1))
page('Знайди нижню платформу',1,1,'1 нижня пластина','Знайди пластину 255 × 150 мм. Зніми захисну плівку. Звір контур і прорізи з моделлю.','Перед позначив учитель. Деталь без тріщин. Контур на моделі відновлено за фото.')
page('Перший мотор',2,2,'1 мотор • штатні кріплення • гвинти з набору','Постав лівий передній мотор. Вал дивиться назовні.','Кріплення і довжину гвинтів підготував учитель.',[((-38,55,LT+60),(-38,55,LT+12.5))])
page('Ще три мотори',3,3,'3 мотори • підготовлені кріплення','Так само закріпи правий передній і два задні мотори.','Жоден гвинт не торкається рухомих деталей.',[((38,55,LT+60),(38,55,LT+12.5)),((-38,-55,LT+60),(-38,-55,LT+12.5)),((38,-55,LT+60),(38,-55,LT+12.5))])
page('Чотири колеса',4,4,'4 колеса','Сумісти отвір із валом. Натискай на втулку, підтримуючи мотор.','Усі колеса обертаються й не труться об пластину.',[((-110,55,11),(-66,55,11)),((110,-55,11),(66,-55,11))])
page('Опори для другого поверху',5,5,'4 опори для проміжку 30 мм • гвинти й шайби','Постав опори у штатні місця, які перевірив учитель. Посадки на моделі приблизні.','Затягни обережно. Акрил не повинен згинатися.',[(tuple([x,y,LT+65]),tuple([x,y,LT+15]))for x,y in P['post_centres_xy']])
page('Відсік під нижньою платформою',6,6,'Відсік 62 × 58 × 18 мм • двосторонній скотч','Без AA приміряй відсік знизу. З учителем очисть і висуши поверхні. Зніми захисний шар скотчу та притисни відсік основою до пластини.','Доступ до AA залишається знизу. Дотримайся часу витримки скотчу. Координати й товщина стрічки ще не виміряні.',[((BX,BY,BT-BH/2-45),(BX,BY,BT-BH/2))],view='bottom')
page('Передній кронштейн',7,7,'1 кронштейн, підігнаний учителем • 2 кріплення','Прикріпи кронштейн до позначених передніх місць.','Він не торкається коліс і не хитається.',[((0,SY_FRONT-11,LT+60),(0,SY_FRONT-11,LT))])
page('П’ять очей унизу',8,8,'1 QTR-MD-05A • 2 бічні затискачі кронштейна','Встав датчик у затискачі. П’ять маленьких віконець дивляться вниз.','Учитель перевіряє зазор 5 мм до підлоги.',[((0,SY_FRONT+40,SZ+2),(0,SY_FRONT,SZ+2))])
page('Верхня платформа',9,9,'1 верхня пластина • 4 ручні гвинти • 4 шайби','Поклади пластину на опори. Не затисни дроти.','Між пластинами 30 мм. Відсік залишається під нижньою пластиною.',[((-40,80,UT+50),(-40,80,UT)),((40,-80,UT+50),(40,-80,UT))])
page('Плата розширення ESP32 30P',10,10,'1 готова плата ESP32 30P • 4 ізоляційні опори • 8 гвинтів','Закріпи плату над верхньою платформою. Її гнізда вже припаяні. Роз’єми USB дивляться назад.','Перемичка стоїть на 3,3 В. Опори й гвинти підібрав учитель.',[((-17,-15,CZ+50),(-17,-15,CZ))])
page('Встав ESP32 DevKit V1',11,11,'1 ESP32 DevKit V1 • 30 контактів: 15 + 15','Сумісти VIN із VIN, а 3V3 із 3V3. Разом з учителем рівно встав два ряди контактів.','Плата на 38 контактів не підходить. Жодна ніжка не загнулася.',[((-17,-10,BZ+50),(-17,-10,BZ))])
page('Драйвери D1 і D2',12,12,'2 модулі Pololu DRV8833 #2130 • 2 наліпки: D1 і D2','Познач дві однакові плати: D1 керує передніми моторами, D2 — задніми. На моделі показано їхнє розташування.','D1 і D2 — назви драйверів. Спосіб їх кріплення ще не визначений: показані опори — лише ескіз.')
page('Живлення та кнопки',13,13,'1 підготовлений S13V30F5 • вимикач S1 • кнопка • їхні кріплення','Закріпи U2 збоку. Постав вимикач і кнопку на позначені місця.','Усі вузли ізольовані знизу. Червоний вимикач доступний.',[((40,-10,UT+60),(40,-10,UT+12)),((45,-46,UT+60),(45,-46,UT+12))])
page('Підключи чотири мотори',14,14,'4 моторні роз’єми JM1…JM4','З’єднай однакові позначки: JM1, JM2, JM3, JM4.','Кожен мотор має свій роз’єм. Дроти не дістають коліс.')
page('Команди для драйверів',15,15,'2 підписані джгути JD1 і JD2','JD1 з’єднується з драйвером D1 передніх моторів, JD2 — з D2 задніх. Монтаж виконуємо після підготовки кріплень.','Сигнали під’єднані до ряду S. Учитель звіряє кожен номер GPIO.')
page('Підключи датчик',16,16,'1 семиконтактний джгут JS','З’єднай JS із датчиком. Кінці біля плати розширення звір із позначками вчителя. Закріпи кабель.','JS має 7 контактів: 3,3 В, земля та 5 сигналів. На платі немає готового гнізда JS.')
page('З’єднай живлення',17,17,'Підготовлена силова проводка • J5 • кабель живлення Micro-USB','Учитель з’єднує J5 від U2 з Micro-USB плати розширення. Потім підключає окремі гілки моторів.','AA ще немає. USB комп’ютера від’єднаний. Круглий роз’єм живлення порожній.')
PAGES.append(dict(kind='inspection',title='Перевір перед живленням'))
page('Встав чотири AA',18,18,'4 однакові заряджені NiMH AA','Вимкни S1 та від’єднай USB. Разом з учителем обережно переверни машинку, підтримуючи корпус. Встав AA у відсік знизу за знаками + і −.','Верх знімати не потрібно. Учитель перевіряє полярність і утримання AA.',[((BX,BY,BT-BH/2-40),(BX,BY,BT-BH/2))],view='bottom')
page('Перевір відсік і зазор',18,None,'Зібрана машинка • рівна поверхня • допомога вчителя','Поверни машинку на колеса. Без живлення обережно прокоти її й перевір утримання відсіку та вільний рух коліс.','До приклеювання зазор був 3–4 мм. З AA й скотчем виміряй його знову: відсік і дроти не мають торкатися підлоги.',view='bottom')
